import { Injectable, computed, inject, signal } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import {
    Building,
    OrganisationService,
    i18n,
    notifySuccess,
} from '@placeos/common';
import { PlaceZone, removeZone } from '@placeos/ts-client';
import { BuildingModalComponent } from './building-modal.component';
import { ItemListModalComponent } from './item-list-modal.component';

export interface BuildingListOptions {
    zone?: string;
    search?: string;
}

import { confirmAction, errorText } from '../ui/modal-actions';
@Injectable({
    providedIn: 'root',
})
export class BuildingManagementService {
    private _org = inject(OrganisationService);
    private _dialog = inject(MatDialog);

    private _options = signal<BuildingListOptions>({});

    public readonly options = this._options.asReadonly();

    public readonly filtered_buildings = computed(() => {
        this._org.initialised();
        const regions = this._org.region_list();
        let list = this._org.building_list();
        const options = this._options();
        if (options.zone) {
            list = list.filter((_) => _.parent_id === options.zone);
        }
        if (options.search) {
            list = list.filter((_) =>
                _.name.toLowerCase().includes(options.search.toLowerCase()),
            );
        }
        for (const bld of list) {
            const parent = regions.find((_) => _.id === bld.parent_id);
            if (parent) {
                (bld as any).region = parent.display_name || parent.name;
            }
            (bld as any).level_count =
                this._org.levelsForBuilding(bld)?.length || 0;
        }
        return list;
    });

    public setFilters(options: Partial<BuildingListOptions>) {
        this._options.update((current) => ({ ...current, ...options }));
    }

    public setSearchString(search: string) {
        this._options.update((current) => ({ ...current, search }));
    }

    public editBuilding(building: PlaceZone = new PlaceZone()) {
        const ref = this._dialog.open(BuildingModalComponent, {
            data: building,
        });
        ref.afterClosed().subscribe((data) => {
            if (data) this._org.addZone(data);
        });
    }

    public async editBuildingMetadata(zone: PlaceZone = new PlaceZone()) {
        const { AppSettingsModalComponent } =
            await import('../ui/app-settings-modal.component');
        const ref = this._dialog.open(AppSettingsModalComponent, {
            data: { zone },
        });
        ref.afterClosed().subscribe((data) => {
            if (data) setTimeout(() => location.reload(), 300);
        });
    }

    public async setAutoRelease(building: PlaceZone) {
        if (!building?.id) return;
        // Loads on demand, so the zone screens do not download its YAML parser
        const { AutoReleaseSettingsModalComponent } =
            await import('./auto-release-settings-modal.component');
        this._dialog.open(AutoReleaseSettingsModalComponent, {
            data: building.id,
        });
    }

    public async setInduction(building: PlaceZone) {
        if (!building?.id) return;
        const { InductionSettingsModalComponent } =
            await import('./induction-settings-modal.component');
        this._dialog.open(InductionSettingsModalComponent, {
            data: building.id,
        });
    }

    public setSupportIssueTypes(building: PlaceZone) {
        if (!building?.id) return;
        this._dialog.open(ItemListModalComponent, {
            data: building.id,
        });
    }

    public async removeBuilding(building: Building) {
        const removed = await confirmAction(
            this._dialog,
            {
                title: i18n('APP.CONCIERGE.BUILDINGS_REMOVE_TITLE'),
                content: i18n('APP.CONCIERGE.BUILDINGS_REMOVE_MSG', {
                    name: building.name,
                }),
                icon: { content: 'delete_forever' },
                confirm_text: i18n('COMMON.REMOVE'),
            },
            {
                loading: i18n('APP.CONCIERGE.BUILDINGS_REMOVE_LOADING'),
                action: () => removeZone(building.id),
                error: (e) =>
                    i18n('APP.CONCIERGE.BUILDINGS_REMOVE_ERROR', {
                        error: errorText(e),
                    }),
            },
        );
        if (!removed) return;
        this._org.removeZone({ id: building.id, tags: ['building'] } as any);
        notifySuccess(i18n('APP.CONCIERGE.BUILDINGS_REMOVE_SUCCESS'));
    }
}
